describe('User Profile - Dark Mode Toggle', () => {
    beforeEach(() => {
        cy.visit('/user-profile');
        cy.login(); // Assuming there's a custom command for login
    });

    it('should enable dark mode when toggled on', () => {
        cy.get('.dark-mode-toggle').check(); // Assuming the toggle is a checkbox
        cy.get('body').should('have.class', 'dark-mode'); // Check if dark mode class is applied
        cy.get('.dark-mode-toggle').should('be.checked'); // Ensure the toggle is checked
    });

    it('should disable dark mode when toggled off', () => {
        cy.get('.dark-mode-toggle').uncheck(); // Toggle off
        cy.get('body').should('not.have.class', 'dark-mode'); // Check if dark mode class is removed
        cy.get('.dark-mode-toggle').should('not.be.checked'); // Ensure the toggle is unchecked
    });
});
